window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ab6fd800f50614cd"]={"versions": [{"id": "FIG-ab6fd800f50614cd", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Komponentendiagramm im Kontext des AUTOSAR Diagnostic Communication Manager (Dcm) innerhalb der Basic Software (BSW, Diagnostic Services Layer). Das Diagramm spezifiziert das Architekturmuster zur Anbindung des Dcm an externe bzw. applikative Funktionen zur Bereitstellung fahrzeugbezogener Diagnoseinformationen für den gesetzlichen On-Board-Diagnosedienst OBD Service $09 (Request Vehicle Information gemäß ISO 15031-5 / SAE J1979).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Dcm</code> («module»): BSW-Modul Diagnostic Communication Manager, dargestellt als Komponente mit herstellerspezifischem Konnektor-Dekorator. Fungiert als Datenkonsument für angeforderte InfoTypes.</li>\n<li><code>InfoTypeServices_&lt;INFOTYPENUMBER&gt;</code> («interface»): Parametrisches Schnittstellen-Template. Der Bezeichner <code>&lt;INFOTYPENUMBER&gt;</code> dient als Platzhalter für die hexadezimale 1-Byte-InfoType-Kennung (z. B. $02 für VIN, $04 für Calibration IDs, $06 für CVN, $08 für IPT). Pro benötigtem InfoType existiert eine separate Schnittstelle bzw. Funktion.</li>\n<li><code>GetInfoTypeValue(return :Std_ReturnType, DataValueBuffer :uint8<em>)</code>: Synchrone Schnittstellenoperation. Parameter: <code>DataValueBuffer</code> als Zeiger auf ein Byte-Array (<code>uint8</em></code>) zur Aufnahme der Nutzdaten. Rückgabewert: <code>Std_ReturnType</code> zur Statusrückmeldung (<code>E_OK</code>, <code>E_NOT_OK</code>).</li>\n<li><code>«configurable»</code>: Gerichtete gestrichelte Abhängigkeitsbeziehung (Dependency/Realization) vom Modul <code>Dcm</code> zur Schnittstelle <code>InfoTypeServices_&lt;INFOTYPENUMBER&gt;</code>, die anzeigt, dass die Zuordnung der Funktionsaufrufe zur Konfigurationszeit parametriert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Beim Empfang einer Diagnoseanforderung für OBD Service $09 extrahiert das Dcm die geforderte InfoType-Nummer aus dem Request-Frame. Über die vorkonfigurierte Zuordnung ruft das Dcm synchron die Funktion <code>GetInfoTypeValue</code> des entsprechenden InfoTypes auf und übergibt eine Zeigerreferenz auf den Zielspeicher (<code>DataValueBuffer</code>). Die aufgerufene Entität schreibt die aktuellen Daten in den Puffer und gibt den Ausführungsstatus zurück. Bei Rückgabe von <code>E_OK</code> assembliert das Dcm die positive OBD-Antwort (Service $49) mit den Pufferdaten; bei <code>E_NOT_OK</code> wird der InfoType ausgelassen bzw. negativ quittiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verpflichtende Schnittstellendefinition für die funktionale Bereitstellung von Fahrzeugdaten unter OBD Service $09. Entwickler müssen für jeden im Fahrzeug unterstützten InfoType eine entsprechende C-Funktion bzw. Port-Operation implementieren und im Dcm-Konfigurationsmodell (Parametergruppe <code>DcmDspVehInfo</code> / <code>DcmDspVehInfoData</code>) konfigurieren. Der Aufrufer (<code>Dcm</code>) stellt den Puffer <code>DataValueBuffer</code> bereit; die Datengröße muss den Spezifikationen der jeweiligen InfoTypes gemäß ISO 15031-5 / SAE J1979 entsprechen, um Pufferüberläufe zu verhindern.</p>"}, {"id": "FIG-b3030465358e481e", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Komponentendiagramm im Kontext des AUTOSAR Diagnostic Communication Manager (Dcm) innerhalb der Basic Software (BSW, Diagnostic Services Layer). Das Diagramm spezifiziert das Architekturmuster zur Anbindung des Dcm an externe bzw. applikative Funktionen zur Bereitstellung fahrzeugbezogener Diagnoseinformationen für den gesetzlichen On-Board-Diagnosedienst OBD Service $09 (Request Vehicle Information gemäß ISO 15031-5 / SAE J1979).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Dcm</code> («module»): BSW-Modul Diagnostic Communication Manager, dargestellt als Komponente mit herstellerspezifischem Konnektor-Dekorator. Fungiert als Datenkonsument für angeforderte InfoTypes.</li>\n<li><code>InfoTypeServices_&lt;INFOTYPENUMBER&gt;</code> («interface»): Parametrisches Schnittstellen-Template. Der Bezeichner <code>&lt;INFOTYPENUMBER&gt;</code> dient als Platzhalter für die hexadezimale 1-Byte-InfoType-Kennung (z. B. $02 für VIN, $04 für Calibration IDs, $06 für CVN, $08 für IPT). Pro benötigtem InfoType existiert eine separate Schnittstelle bzw. Funktion.</li>\n<li><code>GetInfoTypeValue(return :Std_ReturnType, DataValueBuffer :uint8<em>)</code>: Synchrone Schnittstellenoperation. Parameter: <code>DataValueBuffer</code> als Zeiger auf ein Byte-Array (<code>uint8</em></code>) zur Aufnahme der Nutzdaten. Rückgabewert: <code>Std_ReturnType</code> zur Statusrückmeldung (<code>E_OK</code>, <code>E_NOT_OK</code>).</li>\n<li><code>«configurable»</code>: Gerichtete gestrichelte Abhängigkeitsbeziehung (Dependency/Realization) vom Modul <code>Dcm</code> zur Schnittstelle <code>InfoTypeServices_&lt;INFOTYPENUMBER&gt;</code>, die anzeigt, dass die Zuordnung der Funktionsaufrufe zur Konfigurationszeit parametriert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Beim Empfang einer Diagnoseanforderung für OBD Service $09 extrahiert das Dcm die geforderte InfoType-Nummer aus dem Request-Frame. Über die vorkonfigurierte Zuordnung ruft das Dcm synchron die Funktion <code>GetInfoTypeValue</code> des entsprechenden InfoTypes auf und übergibt eine Zeigerreferenz auf den Zielspeicher (<code>DataValueBuffer</code>). Die aufgerufene Entität schreibt die aktuellen Daten in den Puffer und gibt den Ausführungsstatus zurück. Bei Rückgabe von <code>E_OK</code> assembliert das Dcm die positive OBD-Antwort (Service $49) mit den Pufferdaten; bei <code>E_NOT_OK</code> wird der InfoType ausgelassen bzw. negativ quittiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verpflichtende Schnittstellendefinition für die funktionale Bereitstellung von Fahrzeugdaten unter OBD Service $09. Entwickler müssen für jeden im Fahrzeug unterstützten InfoType eine entsprechende C-Funktion bzw. Port-Operation implementieren und im Dcm-Konfigurationsmodell (Parametergruppe <code>DcmDspVehInfo</code> / <code>DcmDspVehInfoData</code>) konfigurieren. Der Aufrufer (<code>Dcm</code>) stellt den Puffer <code>DataValueBuffer</code> bereit; die Datengröße muss den Spezifikationen der jeweiligen InfoTypes gemäß ISO 15031-5 / SAE J1979 entsprechen, um Pufferüberläufe zu verhindern.</p>"}], "trans": [{"from": "FIG-ab6fd800f50614cd", "to": "FIG-b3030465358e481e", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Diagrammrahmen</strong>: Der äußere UML-Rahmen mit der Kopfzeile <code>class OBD Service $09</code> wurde entfernt.</li>\n<li><strong>Modul <code>Dcm</code></strong>: Das nicht-standardisierte Konnektorsymbol (zwei verbundene Kreise) in der rechten unteren Ecke des Modulkastens sowie der Schlagschatten wurden entfernt.</li>\n<li><strong>Schnittstelle <code>InfoTypeServices_&lt;INFOTYPENUMBER&gt;</code></strong>: Der Schriftschnitt des Schnittstellennamens wurde von kursiv auf aufrecht umgestellt; der Schlagschatten der Interface-Box wurde entfernt.</li>\n</ul>"}]};
